/bin/bash -lc "python - <<'PY'
import sim, mujoco
s=sim.Sim()
print('sites:')
for i in range(s.model.nsite):
    print(i, mujoco.mj_id2name(s.model, mujoco.mjtObj.mjOBJ_SITE, i))
print('bodies around ee:')
for name in ['panda_hand','hand','right_hand','left_hand','panda_link8','link7','left_finger','right_finger']:
    try:
        bid = mujoco.mj_name2id(s.model, mujoco.mjtObj.mjOBJ_BODY, name)
        print('body', name, bid, s.model.body_pos[bid])
    except Exception as e:
        print('body', name, 'missing')
print('geoms:')
for i in range(s.model.ngeom):
    n = mujoco.mj_id2name(s.model, mujoco.mjtObj.mjOBJ_GEOM, i)
    if n:
        print(i, n, 'body', s.model.body_id2name(int(s.model.geom_bodyid[i])) if hasattr(s.model,'body_id2name') else int(s.model.geom_bodyid[i]))
PY"

